//! Reflected optional Loam ABI header. Prose owns the crossing contracts.
const std = @import("std");
const abi = @import("c_abi_loam");
const header_emit = @import("header_emit.zig");
const Output = @import("output").Output;
pub const step_name = "gen-header-loam";
pub const outputs = [_]Output{.{ .path = "include/glowcap_loam.h", .generate = generate }};
const names = [_][]const u8{
    "glowcap_loam_validate_configuration",
    "glowcap_loam_metadata_claim",
    "glowcap_loam_store_plan",
    "glowcap_loam_store_finish",
    "glowcap_loam_work_kind",
    "glowcap_loam_work_plan",
    "glowcap_loam_work_finish",
    "glowcap_loam_restore_plan",

    "glowcap_loam_clear_last_error",
