    "glowcap_loam_call_replace_copying",
    "glowcap_loam_call_disclose",
    "glowcap_loam_references_restore",
    "glowcap_loam_references_save_copying",
    "glowcap_loam_call_append_reference",
    "glowcap_loam_call_replace_reference",
    "glowcap_loam_call_remove_reference",
    "glowcap_loam_last_error",
    "glowcap_loam_resource_stage",
    "glowcap_loam_store_abort",
    "glowcap_loam_archive_fingerprint",
};
const Spec = struct {
    pub const c = @import("c_abi_loam");
    pub const emitted_fns = &names;
    pub fn special(comptime T: type) ?[]const u8 {
        if (T == abi.GlowcapLoamRequirementFn or T == ?abi.GlowcapLoamRequirementFn) return "GlowcapLoamRequirementFn";
        if (T == abi.GlowcapLoamInvokeFn or T == ?abi.GlowcapLoamInvokeFn) return "GlowcapLoamInvokeFn";
        if (T == abi.GlowcapLoamReferencesFn or T == ?abi.GlowcapLoamReferencesFn) return "GlowcapLoamReferencesFn";
        if (T == abi.GlowcapLoamEntropyFn or T == ?abi.GlowcapLoamEntropyFn) return "GlowcapLoamEntropyFn";
        if (T == abi.GlowcapLoamKvFn or T == ?abi.GlowcapLoamKvFn) return "GlowcapLoamKvFn";
        return null;
    }
};
const E = header_emit.Emit(Spec);
comptime {
    E.guardFns("c_abi_loam", "glowcap_loam_");
}
fn generate(gpa: std.mem.Allocator) ![]u8 {
    var b: header_emit.Buf = .empty;
    errdefer b.deinit(gpa);
    try b.appendSlice(gpa,
        \\/* GENERATED by zig build gen-header-loam. Do not edit. */
        \\#ifndef GLOWCAP_LOAM_H
        \\#define GLOWCAP_LOAM_H
        \\#include "glowcap_host.h"
        \\#ifdef __cplusplus
        \\extern "C" {
        \\#endif
        \\
    );
    try b.appendSlice(gpa, "typedef struct GlowcapLoamStore GlowcapLoamStore;\n");
    try b.appendSlice(gpa, "typedef struct GlowcapLoamAttachment GlowcapLoamAttachment;\n");
    try b.appendSlice(gpa, "typedef struct GlowcapLoamCall GlowcapLoamCall;\n");
    try b.appendSlice(gpa, "typedef struct GlowcapLoamReferences GlowcapLoamReferences;\n");
    try b.appendSlice(gpa, "typedef struct GlowcapLoamWork GlowcapLoamWork;\n");
    try b.appendSlice(gpa, "typedef struct GlowcapLoamInvocation GlowcapLoamInvocation;\n");
    try b.appendSlice(gpa, "typedef struct GlowcapLoamRequirement GlowcapLoamRequirement;\n");
    try b.appendSlice(gpa, "typedef int32_t (*GlowcapLoamRequirementFn)(void *, const GlowcapLoamInvocation *, GlowcapLoamRequirement *);\n");
    try b.appendSlice(gpa, "typedef int32_t (*GlowcapLoamInvokeFn)(void *, GlowcapLoamCall *, const GlowcapLoamInvocation *);\n");
    try b.appendSlice(gpa, "typedef int32_t (*GlowcapLoamReferencesFn)(void *, GlowcapLoamReferences *, const GlowcapLoamInvocation *);\n");
    try b.appendSlice(gpa, "typedef int32_t (*GlowcapLoamEntropyFn)(void *, uint8_t *, size_t);\n");
    try E.emitStruct(&b, gpa, abi.GlowcapLoamObject, "GlowcapLoamObject", &@as([@typeInfo(abi.GlowcapLoamObject).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamSchema, "GlowcapLoamSchema", &@as([@typeInfo(abi.GlowcapLoamSchema).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamLimits, "GlowcapLoamLimits", &@as([@typeInfo(abi.GlowcapLoamLimits).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamBound, "GlowcapLoamBound", &@as([@typeInfo(abi.GlowcapLoamBound).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamConstraint, "GlowcapLoamConstraint", &@as([@typeInfo(abi.GlowcapLoamConstraint).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamPolicy, "GlowcapLoamPolicy", &@as([@typeInfo(abi.GlowcapLoamPolicy).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitBareStruct(&b, gpa, abi.GlowcapLoamRequirement, "GlowcapLoamRequirement", &@as([@typeInfo(abi.GlowcapLoamRequirement).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitBareStruct(&b, gpa, abi.GlowcapLoamInvocation, "GlowcapLoamInvocation", &@as([@typeInfo(abi.GlowcapLoamInvocation).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamMethod, "GlowcapLoamMethod", &@as([@typeInfo(abi.GlowcapLoamMethod).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamContent, "GlowcapLoamContent", &@as([@typeInfo(abi.GlowcapLoamContent).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamResource, "GlowcapLoamResource", &@as([@typeInfo(abi.GlowcapLoamResource).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamPolicyValue, "GlowcapLoamPolicyValue", &@as([@typeInfo(abi.GlowcapLoamPolicyValue).@"struct".field_names.len][]const u8, @splat("")));
    try E.emitStruct(&b, gpa, abi.GlowcapLoamBytes, "GlowcapLoamBytes", &.{ "Borrowed bytes, valid through the plan call.", "Byte count.", "Zero means absent; one means present, including an empty value." });
    try b.appendSlice(gpa, "typedef int32_t (*GlowcapLoamKvFn)(void *, uint32_t, const uint8_t *, size_t, const GlowcapLoamBytes *, GlowcapLoamBytes *);\n");
    try E.emitConst(&b, gpa, "GLOWCAP_LOAM_METADATA_SIZE");
    try E.emitConst(&b, gpa, "GLOWCAP_LOAM_ARCHIVE_FINGERPRINT");
    try E.emitFn(&b, gpa, "glowcap_loam_store_new", &.{ "metadata", "metadata_len", "schemas", "schema_count", "limits", "out_store" }, "Construct a portable Store from exclusively claimed encoded metadata. Schema descriptors are copied. Inputs borrow for this call; out_store owns one release. No backend is opened.");
    try E.emitFn(&b, gpa, "glowcap_loam_store_new_in", &.{ "context", "metadata", "metadata_len", "schemas", "schema_count", "limits", "out_store" }, "Construct a portable Store using the Context allocator for every Store and attachment allocation. The Context and its allocator callbacks outlive the Store and all its borrows. Metadata and schema rules match store_new.");
    try E.emitFn(&b, gpa, "glowcap_loam_store_release", &.{"raw"}, "Release a standalone Store. Backend-owned Stores release through their backend owner. Busy leaves the handle alive while attachments, workers, transactions, or leases survive.");
    try E.emitFn(&b, gpa, "glowcap_loam_attach", &.{ "raw", "host_handle", "contents", "content_count", "entropy", "ctx", "out_attachment" }, "Attach copied content declarations to an existing Host and Store. Contexts borrow until successful attachment release. Callbacks run synchronously on the Host thread and cannot unwind or reenter driving verbs. Entropy fills fresh unpredictable bytes across restarts.");
    try E.emitFn(&b, gpa, "glowcap_loam_attachment_release", &.{"raw"}, "Release a quiescent attachment. Busy preserves the attachment, its Host borrow, contexts, and outstanding work. Held Host capabilities remain releasable and reject later calls.");
    try E.emitFn(&b, gpa, "glowcap_loam_advance", &.{ "raw", "out_progress" }, "Advance shared preparation and installation on the Host thread, outside callbacks. This performs no storage I/O.");
    try E.emitFn(&b, gpa, "glowcap_loam_next_work", &.{ "raw", "recovery", "out_work" }, "Take one submitted storage effect. The returned work owns immutable borrowed batch/read storage until its worker retires. An uncertain batch automatically selects recovery after the original worker has completed and been released; recovery=1 explicitly requires that state. Complete and release each work exactly once.");
    try E.emitFn(&b, gpa, "glowcap_loam_work_complete", &.{ "raw", "out_completed" }, "After joining the storage worker, install its result on the Host thread. out_completed reports whether the handle is completed, including refusal after consumption. A reentrant call or unfinished worker leaves it uncompleted and owned. Repeated completion is stale. Unknown writes retain their recovery barrier.");
    try E.emitFn(&b, gpa, "glowcap_loam_work_release", &.{"raw"}, "Release a completed work handle. Busy refuses an unretired worker. Null succeeds. Releasing a live worker is never cancellation.");
    try E.emitFn(&b, gpa, "glowcap_loam_call_reply", &.{ "call", "value" }, "Copy a passable reply into the retained call arena during a callback. A second reply refuses. Capability disclosure is checked by the shared managed service before settlement.");
    try E.emitFn(&b, gpa, "glowcap_loam_call_replace_copying", &.{ "call", "bytes", "len" }, "Copy a replacement payload into the retained call arena. The shared transaction persists it with the admitted operation. Inputs borrow for this call.");
    try E.emitFn(&b, gpa, "glowcap_loam_call_disclose", &.{ "call", "index", "dependent", "out_value" }, "Declare a strong saved application field in the current reply. Application indices omit the protected resource binding. dependent=1 returns a facet mediated by both the invoking grant and saved authority. The returned value borrows the call arena.");
    try E.emitFn(&b, gpa, "glowcap_loam_references_restore", &.{ "raw", "index" }, "Declare a stored field for restoration after current grant admission. The token borrows only through the reference callback. Duplicate or absent fields refuse.");
    try E.emitFn(&b, gpa, "glowcap_loam_references_save_copying", &.{ "raw", "reference", "uri", "uri_len" }, "Declare exact held authority for saving. Local targets need no URI. A foreign target needs an established sturdy URI verified through Host before content staging. URI bytes copy before return; declarations are bounded.");
    try E.emitFn(&b, gpa, "glowcap_loam_call_append_reference", &.{ "call", "reference" }, "Append a strong saved field after surviving committed fields. Foreign targets need declared preparation. Payload and fields share one transaction; no authority escapes before confirmed commit.");
    try E.emitFn(&b, gpa, "glowcap_loam_call_replace_reference", &.{ "call", "index", "reference" }, "Replace a committed strong field with exact held authority. Indices name the committed list throughout invocation; duplicate edits refuse. Foreign targets need declared preparation.");
    try E.emitFn(&b, gpa, "glowcap_loam_call_remove_reference", &.{ "call", "index" }, "Remove a committed strong field without revoking its target or publication. Indices name the committed list throughout invocation. Payload and removals commit together.");
    try E.emitFn(&b, gpa, "glowcap_loam_last_error", &.{ "buf", "len" }, "Copy the immediate thread-local Loam error into caller storage. Returns bytes copied. Text is diagnostic; return codes own branching.");
    try E.emitFn(&b, gpa, "glowcap_loam_resource_stage", &.{ "raw", "policy", "owner_id", "kind", "schema", "version", "payload", "payload_len", "delegation_depth", "out_resource" }, "Privileged creation stages a fresh owner, root resource, grant, content, and use/control endpoints atomically. The first content edge strongly retains its resource and is excluded from application field indices. Owner identity is fresh namespace data, not authority. Output names remain provisional until commit. Failure aborts staging; no capability escapes.");
    try E.emitFn(&b, gpa, "glowcap_loam_store_abort", &.{"raw"}, "Abort unsubmitted staging before any backend write. Refuses an attached Store or an in-flight write. An LMDB companion commit consumes its transaction through the shared completion contract.");
    try E.emitFn(&b, gpa, "glowcap_loam_archive_fingerprint", &.{}, "Return this archive's reflected callable and layout fingerprint before the first ordinary call.");
    try E.emitFn(&b, gpa, "glowcap_loam_work_report_unknown", &.{"raw"}, "After joining the original write worker, report an indeterminate commit. Complete and release this work before taking recovery. Other effect kinds refuse.");
    inline for (.{ "GLOWCAP_LOAM_ERR_RECOVERY_REQUIRED", "GLOWCAP_LOAM_ERR_STALE_COMPLETION", "GLOWCAP_LOAM_ERR_DENIED", "GLOWCAP_LOAM_ERR_UNCHANGED", "GLOWCAP_LOAM_ERR_APPLICATION" }) |name| try E.emitConst(&b, gpa, name);
    try E.emitFn(&b, gpa, "glowcap_loam_has_pending_work", &.{ "raw", "out_pending" }, "Observe pending shared work on the Host thread. A parked effect is pending without necessarily being runnable; advance reports actual transitions.");
    try E.emitFn(&b, gpa, "glowcap_loam_policy_value", &.{ "policy", "requirement", "out_value" }, "Validate a bounded descriptor and construct policy terms from declared keys and bounds. Inputs borrow for this call; the shared Zig policy algebra produces the allocation-free output.");
    try E.emitFn(&b, gpa, "glowcap_loam_work_report_unstarted", &.{"raw"}, "After proving a submitted executor job never ran, report failure without inventing a commit. A write completes unchanged; an unstarted recovery leaves the existing indeterminate barrier intact. Complete and release the work on the Host thread.");
    try E.emitFn(&b, gpa, "glowcap_loam_clear_last_error", &.{}, "Clear this archive's thread-local diagnostic slot.");
    try E.emitFn(&b, gpa, "glowcap_loam_metadata_claim", &.{ "identity", "create", "previous", "previous_len", "out_metadata", "out_len" }, "Compute a fresh exclusive claim from stored metadata or explicit creation. The adapter atomically persists the GLOWCAP_LOAM_METADATA_SIZE output under its exclusive lock before exposing a constructed Store. Existing data never resets or changes identity.");
    try E.emitFn(&b, gpa, "glowcap_loam_store_plan", &.{ "raw", "recovery", "callback", "context" }, "Evaluate startup commit or recovery in the adapter atomic transaction. KV operations 0=get, 1=put, 2=remove borrow through this call. Get returns WOULD_BLOCK for an unloaded row, OK with present=0 for absence. Tentative writes must be discarded before retry. No terminal outcome or installation is implied.");
    try E.emitFn(&b, gpa, "glowcap_loam_store_finish", &.{ "raw", "recovery", "outcome" }, "After the startup transaction retires, report 0=completed plan, 1=known abort, 2=indeterminate write. Recovery refuses indeterminate or aborted outcomes and preserves its barrier. Only successful installation permits exposing provisional resource names.");
    try E.emitFn(&b, gpa, "glowcap_loam_work_kind", &.{ "raw", "out_kind" }, "Report 0=read, 1=write, 2=name lookup, 3=recovery. Only writes need a readwrite transaction; recovery observes committed metadata.");
    try E.emitFn(&b, gpa, "glowcap_loam_work_plan", &.{ "raw", "callback", "context" }, "Evaluate a submitted effect through transaction-local KV callbacks. Borrowed rows remain valid through the call; put copies into an adapter overlay. WOULD_BLOCK requests another input without consuming work. Discard the overlay on retry. Successful evaluation retains a plan until the terminal event; it does not install or retire work.");
    try E.emitFn(&b, gpa, "glowcap_loam_work_finish", &.{ "raw", "outcome" }, "After physical database retirement, report 0=completed plan, 1=known abort, 2=indeterminate write. Then complete and release work on the Host thread. Only writes admit an indeterminate outcome. Duplicate retirement refuses.");
    try E.emitFn(&b, gpa, "glowcap_loam_restore_plan", &.{ "raw", "object", "callback", "context", "out_ref" }, "Restore a rooted endpoint from adapter-owned transaction-local rows. Missing rows return WOULD_BLOCK. The adapter retains the returned Host occurrence until the read transaction terminates and releases it on abort. Trusted persisted names never bypass endpoint validation.");
    try E.emitFn(&b, gpa, "glowcap_loam_validate_configuration", &.{ "schemas", "schema_count", "limits" }, "Validate copied schema descriptors and bounded Store configuration without opening or claiming physical storage.");
    try E.assertAllEmitted(&b, step_name);
    try b.appendSlice(gpa, "#ifdef __cplusplus\n}\n#endif\n#endif\n");
    return b.toOwnedSlice(gpa);
}
